import React from 'react';
import './Carrito.css';

function Carrito({ cartItems }) {
  const removeFromCart = (productId) => {
    // Lógica para eliminar un producto del carrito
  };

  const clearCart = () => {
    // Lógica para vaciar el carrito
  };

  const handleCheckout = () => {
    alert('¡Compra confirmada!');
    clearCart();
  };

  const total = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return (
    <div className="carrito-container">
      <h2>Carrito de Compras</h2>

      {cartItems.length === 0 ? (
        <p className="empty-cart">Tu carrito está vacío</p>
      ) : (
        <div className="cart-items">
          {cartItems.map(product => (
            <div key={product.id} className="cart-item">
              <div className="item-info">
                <span className="item-name">{product.name}</span>
                <span className="item-price">${product.price}</span>
                <span className="item-quantity">Cantidad: {product.quantity}</span>
              </div>
              <button className="remove-btn" onClick={() => removeFromCart(product.id)}>Eliminar</button>
            </div>
          ))}

          <div className="cart-total">
            <strong>Total:</strong> ${total.toFixed(2)}
          </div>

          <div className="cart-actions">
            <button className="clear-btn" onClick={clearCart}>Vaciar Carrito</button>
            <button className="checkout-btn" onClick={handleCheckout}>Confirmar Compra</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default Carrito;
